package com.sweforge.pricing;

public final class DiscountPolicy {
    private DiscountPolicy() { }

    public static double discountRate(int subtotalCents, CustomerTier customerTier) {
        if (customerTier == CustomerTier.VIP) return 0.20;
        if (subtotalCents >= 10_000) return 0.10;
        return 0.0;
    }
}

public static double discountRate(int subtotalCents, CustomerTier customerTier) {
    if (customerTier == CustomerTier.VIP) return 0.20;
    if (subtotalCents >= 10_000) return 0.10;
    return 0.0;
}

package com.sweforge.pricing;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.assertEquals;

class PricingCalculatorTest {
      private final PricingCalculator calculator = new PricingCalculator();

      @Test void smallRegularOrderHasNoDiscount() {
          assertEquals(5_500, calculator.calculateTotalCents(new Order(List.of(new Item(2_500), new Item(3_000)))));
      }

      @Test void largeRegularOrderGetsBulkDiscount() {
          assertEquals(9_900, calculator.calculateTotalCents(new Order(List.of(new Item(6_000), new Item(5_000)))));
      }

      @Test void vipOrderGetsVipDiscount() {
          assertEquals(4_800, calculator.calculateTotalCents(new Order(List.of(new Item(4_000), new Item(2_000)), CustomerTier.VIP)));
      }

      @Test void justBelowThresholdHasNoDiscount() {
          assertEquals(9_999, calculator.calculateTotalCents(new Order(List.of(new Item(9_999)))));
      }

      @Test void atThresholdGetsBulkDiscount() {
          assertEquals(9_000, calculator.calculateTotalCents(new Order(List.of(new Item(10_000)))));
      }

      @Test void justAboveThresholdGetsBulkDiscount() {
          assertEquals(9_001, calculator.calculateTotalCents(new Order(List.of(new Item(10_001)))));
      }
}

